mapper.select:
select m.registerToday, m.registerTotal, m.kycToday, m.kycTotal, m.pendingKyc, ck.checkinToday, ck.checkinTotal, ck.checkinRewardTodayCny, ck.checkinRewardTodayUsdt, ck.checkinRewardTotalCny, ck.checkinRewardTotalUsdt, rch.rechargeTodayCny, rch.rechargeTodayUsdt, rch.rechargeTotalCny, rch.rechargeTotalUsdt, rch.rechargeTodayCount, rch.rechargeTotalCount, rch.rechargeTodayUsers, rch.rechargeTotalUsers, rch.pendingRecharge, od.subscribeTodayUsers, od.subscribeTotalUsers, od.pullTodayCount, od.pullTotalCount, od.pullTodayCny, od.pullTodayUsdt, od.pullTotalCny, od.pullTotalUsdt, od.holdingOrders, od.holdingUsers, fb.subscribeNewToday, fb.subscribeNewTotal, wd.wdProductTodayCny, wd.wdProductTodayUsdt, wd.wdProductTotalCny, wd.wdProductTotalUsdt, wd.wdProductTodayCount, wd.wdProductTotalCount, wd.wdPromoTodayCny, wd.wdPromoTodayUsdt, wd.wdPromoTotalCny, wd.wdPromoTotalUsdt, wd.wdPromoTodayCount, wd.wdPromoTotalCount, wd.wdAssistTodayCny, wd.wdAssistTodayUsdt, wd.wdAssistTotalCny, wd.wdAssistTotalUsdt, wd.wdAssistTodayCount, wd.wdAssistTotalCount, wd.wdTotalTodayCny, wd.wdTotalTodayUsdt, wd.wdTotalTotalCny, wd.wdTotalTotalUsdt, wd.wdTotalTodayCount, wd.wdTotalTotalCount, wd.wdApplyTodayCny, wd.wdApplyTodayUsdt, wd.wdApplyTodayCount, wd.pendingWithdraw, wd.pendingWithdrawCny, wd.pendingWithdrawUsdt, lg.rebateTodayCny, lg.rebateTodayUsdt, lg.rebateTotalCny, lg.rebateTotalUsdt, lg.rebateTodayCount, lg.rebateTotalCount, lg.commissionTodayCny, lg.commissionTodayUsdt, lg.commissionTotalCny, lg.commissionTotalUsdt, lg.commissionTodayCount, lg.commissionTotalCount, lg.inviteTodayCny, lg.inviteTodayUsdt, lg.inviteTotalCny, lg.inviteTotalUsdt, wa.walletCnyAvailable, wa.walletUsdtAvailable, wa.walletCnyFrozen, wa.walletUsdtFrozen, lr.pendingLevelReward from ( select ifnull(sum(case when create_time >= #{dayStart} and create_time < #{dayEnd} then 1 else 0 end), 0) as registerToday, count(*) as registerTotal, ifnull(sum(case when kyc_status = '1' and update_time >= #{dayStart} and update_time < #{dayEnd} then 1 else 0 end), 0) as kycToday, ifnull(sum(case when kyc_status = '1' then 1 else 0 end), 0) as kycTotal, ifnull(sum(case when kyc_status = '0' then 1 else 0 end), 0) as pendingKyc from biz_member where ifnull(test_flag, '0') = '0' ) m cross join ( select ifnull(sum(case when c.checkin_date = #{dayText} then 1 else 0 end), 0) as checkinToday, count(*) as checkinTotal, ifnull(sum(case when c.currency = 'CNY' and c.checkin_date = #{dayText} then c.amount else 0 end), 0) as checkinRewardTodayCny, ifnull(sum(case when c.currency = 'USDT' and c.checkin_date = #{dayText} then c.amount else 0 end), 0) as checkinRewardTodayUsdt, ifnull(sum(case when c.currency = 'CNY' then c.amount else 0 end), 0) as checkinRewardTotalCny, ifnull(sum(case when c.currency = 'USDT' then c.amount else 0 end), 0) as checkinRewardTotalUsdt from biz_checkin c
) ck cross join ( select ifnull(sum(case when and r.currency = 'CNY' then r.amount else 0 end), 0) as rechargeTodayCny, ifnull(sum(case when and r.currency = 'USDT' then r.amount else 0 end), 0) as rechargeTodayUsdt, ifnull(sum(case when r.status = '1' and r.currency = 'CNY' then r.amount else 0 end), 0) as rechargeTotalCny, ifnull(sum(case when r.status = '1' and r.currency = 'USDT' then r.amount else 0 end), 0) as rechargeTotalUsdt, ifnull(sum(case when then 1 else 0 end), 0) as rechargeTodayCount, ifnull(sum(case when r.status = '1' then 1 else 0 end), 0) as rechargeTotalCount, count(distinct case when then r.member_id end) as rechargeTodayUsers, count(distinct case when r.status = '1' then r.member_id end) as rechargeTotalUsers, ifnull(sum(case when r.status = '0' then 1 else 0 end), 0) as pendingRecharge from biz_recharge r
) rch cross join ( select count(distinct case when o.create_time >= #{dayStart} and o.create_time < #{dayEnd} then o.member_id end) as subscribeTodayUsers, count(distinct o.member_id) as subscribeTotalUsers, ifnull(sum(case when o.create_time >= #{dayStart} and o.create_time < #{dayEnd} then 1 else 0 end), 0) as pullTodayCount, count(*) as pullTotalCount, ifnull(sum(case when o.currency = 'CNY' and o.create_time >= #{dayStart} and o.create_time < #{dayEnd} then o.price else 0 end), 0) as pullTodayCny, ifnull(sum(case when o.currency = 'USDT' and o.create_time >= #{dayStart} and o.create_time < #{dayEnd} then o.price else 0 end), 0) as pullTodayUsdt, ifnull(sum(case when o.currency = 'CNY' then o.price else 0 end), 0) as pullTotalCny, ifnull(sum(case when o.currency = 'USDT' then o.price else 0 end), 0) as pullTotalUsdt, ifnull(sum(case when o.status = '0' then 1 else 0 end), 0) as holdingOrders, count(distinct case when o.status = '0' then o.member_id end) as holdingUsers from biz_order o
) od cross join ( select ifnull(sum(case when t.first_time >= #{dayStart} and t.first_time < #{dayEnd} then 1 else 0 end), 0) as subscribeNewToday, count(*) as subscribeNewTotal from ( select min(o.create_time) as first_time from biz_order o
group by o.member_id ) t ) fb cross join ( select ifnull(sum(case when and ifnull(w.wallet_type_code, 'PRODUCT') = 'PRODUCT' and w.currency = 'CNY' then w.amount else 0 end), 0) as wdProductTodayCny, ifnull(sum(case when and ifnull(w.wallet_type_code, 'PRODUCT') = 'PRODUCT' and w.currency = 'USDT' then w.amount else 0 end), 0) as wdProductTodayUsdt, ifnull(sum(case when w.status = '1' and ifnull(w.wallet_type_code, 'PRODUCT') = 'PRODUCT' and w.currency = 'CNY' then w.amount else 0 end), 0) as wdProductTotalCny, ifnull(sum(case when w.status = '1' and ifnull(w.wallet_type_code, 'PRODUCT') = 'PRODUCT' and w.currency = 'USDT' then w.amount else 0 end), 0) as wdProductTotalUsdt, ifnull(sum(case when and ifnull(w.wallet_type_code, 'PRODUCT') = 'PRODUCT' then 1 else 0 end), 0) as wdProductTodayCount, ifnull(sum(case when w.status = '1' and ifnull(w.wallet_type_code, 'PRODUCT') = 'PRODUCT' then 1 else 0 end), 0) as wdProductTotalCount,
ifnull(sum(case when and ifnull(w.wallet_type_code, '') = 'PROMO' and w.currency = 'CNY' then w.amount else 0 end), 0) as wdPromoTodayCny, ifnull(sum(case when and ifnull(w.wallet_type_code, '') = 'PROMO' and w.currency = 'USDT' then w.amount else 0 end), 0) as wdPromoTodayUsdt, ifnull(sum(case when w.status = '1' and ifnull(w.wallet_type_code, '') = 'PROMO' and w.currency = 'CNY' then w.amount else 0 end), 0) as wdPromoTotalCny, ifnull(sum(case when w.status = '1' and ifnull(w.wallet_type_code, '') = 'PROMO' and w.currency = 'USDT' then w.amount else 0 end), 0) as wdPromoTotalUsdt, ifnull(sum(case when and ifnull(w.wallet_type_code, '') = 'PROMO' then 1 else 0 end), 0) as wdPromoTodayCount, ifnull(sum(case when w.status = '1' and ifnull(w.wallet_type_code, '') = 'PROMO' then 1 else 0 end), 0) as wdPromoTotalCount,
ifnull(sum(case when and (ifnull(w.wallet_type_code, '') = 'ASSIST' or ifnull(w.remark, '') like concat(convert(unhex('E58AA9E58A9B') using utf8mb4), '%') or upper(ifnull(w.remark, '')) like 'ASSIST%') and w.currency = 'CNY' then w.amount else 0 end), 0) as wdAssistTodayCny, ifnull(sum(case when and (ifnull(w.wallet_type_code, '') = 'ASSIST' or ifnull(w.remark, '') like concat(convert(unhex('E58AA9E58A9B') using utf8mb4), '%') or upper(ifnull(w.remark, '')) like 'ASSIST%') and w.currency = 'USDT' then w.amount else 0 end), 0) as wdAssistTodayUsdt, ifnull(sum(case when w.status = '1' and (ifnull(w.wallet_type_code, '') = 'ASSIST' or ifnull(w.remark, '') like concat(convert(unhex('E58AA9E58A9B') using utf8mb4), '%') or upper(ifnull(w.remark, '')) like 'ASSIST%') and w.currency = 'CNY' then w.amount else 0 end), 0) as wdAssistTotalCny, ifnull(sum(case when w.status = '1' and (ifnull(w.wallet_type_code, '') = 'ASSIST' or ifnull(w.remark, '') like concat(convert(unhex('E58AA9E58A9B') using utf8mb4), '%') or upper(ifnull(w.remark, '')) like 'ASSIST%') and w.currency = 'USDT' then w.amount else 0 end), 0) as wdAssistTotalUsdt, ifnull(sum(case when and (ifnull(w.wallet_type_code, '') = 'ASSIST' or ifnull(w.remark, '') like concat(convert(unhex('E58AA9E58A9B') using utf8mb4), '%') or upper(ifnull(w.remark, '')) like 'ASSIST%') then 1 else 0 end), 0) as wdAssistTodayCount, ifnull(sum(case when w.status = '1' and (ifnull(w.wallet_type_code, '') = 'ASSIST' or ifnull(w.remark, '') like concat(convert(unhex('E58AA9E58A9B') using utf8mb4), '%') or upper(ifnull(w.remark, '')) like 'ASSIST%') then 1 else 0 end), 0) as wdAssistTotalCount,
ifnull(sum(case when and w.currency = 'CNY' then w.amount else 0 end), 0) as wdTotalTodayCny, ifnull(sum(case when and w.currency = 'USDT' then w.amount else 0 end), 0) as wdTotalTodayUsdt, ifnull(sum(case when w.status = '1' and w.currency = 'CNY' then w.amount else 0 end), 0) as wdTotalTotalCny, ifnull(sum(case when w.status = '1' and w.currency = 'USDT' then w.amount else 0 end), 0) as wdTotalTotalUsdt, ifnull(sum(case when then 1 else 0 end), 0) as wdTotalTodayCount, ifnull(sum(case when w.status = '1' then 1 else 0 end), 0) as wdTotalTotalCount,
ifnull(sum(case when w.create_time >= #{dayStart} and w.create_time < #{dayEnd} and w.currency = 'CNY' then w.amount else 0 end), 0) as wdApplyTodayCny, ifnull(sum(case when w.create_time >= #{dayStart} and w.create_time < #{dayEnd} and w.currency = 'USDT' then w.amount else 0 end), 0) as wdApplyTodayUsdt, ifnull(sum(case when w.create_time >= #{dayStart} and w.create_time < #{dayEnd} then 1 else 0 end), 0) as wdApplyTodayCount,
ifnull(sum(case when w.status in ('0', '3') then 1 else 0 end), 0) as pendingWithdraw, ifnull(sum(case when w.status in ('0', '3') and w.currency = 'CNY' then w.amount else 0 end), 0) as pendingWithdrawCny, ifnull(sum(case when w.status in ('0', '3') and w.currency = 'USDT' then w.amount else 0 end), 0) as pendingWithdrawUsdt from biz_withdraw w
) wd cross join ( select ifnull(sum(case when l.biz_type = 'REBATE' and l.create_time >= #{dayStart} and l.create_time < #{dayEnd} and l.currency = 'CNY' then l.amount else 0 end), 0) as rebateTodayCny, ifnull(sum(case when l.biz_type = 'REBATE' and l.create_time >= #{dayStart} and l.create_time < #{dayEnd} and l.currency = 'USDT' then l.amount else 0 end), 0) as rebateTodayUsdt, ifnull(sum(case when l.biz_type = 'REBATE' and l.currency = 'CNY' then l.amount else 0 end), 0) as rebateTotalCny, ifnull(sum(case when l.biz_type = 'REBATE' and l.currency = 'USDT' then l.amount else 0 end), 0) as rebateTotalUsdt, ifnull(sum(case when l.biz_type = 'REBATE' and l.create_time >= #{dayStart} and l.create_time < #{dayEnd} then 1 else 0 end), 0) as rebateTodayCount, ifnull(sum(case when l.biz_type = 'REBATE' then 1 else 0 end), 0) as rebateTotalCount, ifnull(sum(case when l.biz_type = 'COMMISSION' and l.create_time >= #{dayStart} and l.create_time < #{dayEnd} and l.currency = 'CNY' then l.amount else 0 end), 0) as commissionTodayCny, ifnull(sum(case when l.biz_type = 'COMMISSION' and l.create_time >= #{dayStart} and l.create_time < #{dayEnd} and l.currency = 'USDT' then l.amount else 0 end), 0) as commissionTodayUsdt, ifnull(sum(case when l.biz_type = 'COMMISSION' and l.currency = 'CNY' then l.amount else 0 end), 0) as commissionTotalCny, ifnull(sum(case when l.biz_type = 'COMMISSION' and l.currency = 'USDT' then l.amount else 0 end), 0) as commissionTotalUsdt, ifnull(sum(case when l.biz_type = 'COMMISSION' and l.create_time >= #{dayStart} and l.create_time < #{dayEnd} then 1 else 0 end), 0) as commissionTodayCount, ifnull(sum(case when l.biz_type = 'COMMISSION' then 1 else 0 end), 0) as commissionTotalCount, ifnull(sum(case when l.biz_type = 'INVITE' and l.create_time >= #{dayStart} and l.create_time < #{dayEnd} and l.currency = 'CNY' then l.amount else 0 end), 0) as inviteTodayCny, ifnull(sum(case when l.biz_type = 'INVITE' and l.create_time >= #{dayStart} and l.create_time < #{dayEnd} and l.currency = 'USDT' then l.amount else 0 end), 0) as inviteTodayUsdt, ifnull(sum(case when l.biz_type = 'INVITE' and l.currency = 'CNY' then l.amount else 0 end), 0) as inviteTotalCny, ifnull(sum(case when l.biz_type = 'INVITE' and l.currency = 'USDT' then l.amount else 0 end), 0) as inviteTotalUsdt from biz_wallet_log l
where l.biz_type in ('REBATE', 'COMMISSION', 'INVITE') ) lg cross join ( select ifnull(sum(case when w.currency = 'CNY' then w.available else 0 end), 0) as walletCnyAvailable, ifnull(sum(case when w.currency = 'USDT' then w.available else 0 end), 0) as walletUsdtAvailable, ifnull(sum(case when w.currency = 'CNY' then w.frozen else 0 end), 0) as walletCnyFrozen, ifnull(sum(case when w.currency = 'USDT' then w.frozen else 0 end), 0) as walletUsdtFrozen from biz_wallet w
) wa cross join ( select count(*) as pendingLevelReward from biz_level_reward_grant g inner join biz_member mb on mb.member_id = g.member_id and ifnull(mb.test_flag, '0') = '0' where g.status = '0' ) lr

select date_format(coalesce(r.audit_time, r.create_time), '%Y-%m-%d') as dayKey, ifnull(sum(r.amount), 0) as amount
from biz_recharge r

where r.status = '1' and r.currency = 'CNY'
  and coalesce(r.audit_time, r.create_time) >= #{begin}
  and coalesce(r.audit_time, r.create_time) < #{end}
group by date_format(coalesce(r.audit_time, r.create_time), '%Y-%m-%d')

select date_format(coalesce(w.audit_time, w.create_time), '%Y-%m-%d') as dayKey, ifnull(sum(w.amount), 0) as amount
from biz_withdraw w

where w.status = '1' and w.currency = 'CNY'
  and coalesce(w.audit_time, w.create_time) >= #{begin}
  and coalesce(w.audit_time, w.create_time) < #{end}
group by date_format(coalesce(w.audit_time, w.create_time), '%Y-%m-%d')
